def _decode(blob):
 it=iter(base64.b64decode(blob,validate=True))
 def uv():
  v=s=0
  while True:
   c=next(it);v|=(c&127)<<s
   if c<128:return v
   s+=7;assert s<=35
 def sv():
  v=uv();return -(v+1)//2 if v&1 else v//2
 rows=[];last=0
 for _ in range(uv()):
  n=sv();assert n!=0
  if n>0:last+=sv();rows.append((n,last))
  else:rows.append((n,-1))
 assert next(it,None)is None
 return rows

def _encode(rows):
 data=bytearray()
 def uv(v):
  assert v>=0
  while v>=128:data.append((v&127)|128);v>>=7
  data.append(v)
 def sv(v):uv(-2*v-1 if v<0 else 2*v)
 uv(len(rows));last=0
 for n,x in rows:
  sv(n)
  if n>0:sv(x-last);last=x
 return base64.b64encode(data).decode()

def _audit(rows,expected=None):
 assert tuple(n for n,x in rows)==PUBLIC_COMMANDS,'public12 commands changed'
 gaps=[];pipes=[None];occ=bytearray();T=V=0
 def add(l,r):
  if l>=r:return
  k=bisect.bisect_left(gaps,(l,))
  if k and gaps[k-1][1]==l:l=gaps.pop(k-1)[0];k-=1
  if k<len(gaps)and gaps[k][0]==r:r=gaps.pop(k)[1]
  gaps.insert(k,(l,r))
 for t,(n,x)in enumerate(rows):
  if n>0:
   assert 1<=n<=40 and 0<=x and x+n<=100000000
   fitting=any(r-l>=n for l,r in gaps)
   tail=gaps[-1][0]if gaps and gaps[-1][1]==T else T
   minimum=T if fitting else T+20*max(0,(tail+n-T+19)//20)
   nt=max(T,20*((x+n+19)//20));assert nt<=minimum,('guard5 minimal-dig',t+1)
   add(T,nt);k=bisect.bisect_right(gaps,(x,10**9))-1;assert k>=0,('physical gap missing',t+1)
   l,r=gaps.pop(k);assert l<=x and x+n<=r,('overlap',t+1)
   assert x==l or x+n==r,('guard5 edge',t+1)
   add(l,x);add(x+n,r);occ.extend(b'\0'*(nt-len(occ)))
   assert not any(occ[x:x+n]),('independent occupancy overlap',t+1)
   occ[x:x+n]=b'\1'*n;pipes.append((x,n));V+=n;reply=((nt-T)//20,x);T=nt
  else:
   p=-n;assert 0<p<len(pipes)and pipes[p]is not None
   x,L=pipes[p];assert all(occ[x:x+L]),('independent deletion missing',t+1)
   occ[x:x+L]=b'\0'*L;add(x,x+L);V-=L;pipes[p]=None;reply=(x,)
  if expected is not None:assert reply==expected[t],('response/physics differs',t+1)
  if t<FIXED:assert reply==BASELINE_PREFIX[t],('fixed154 differs',t+1)
  assert T<=BASELINE_T[t],('all-prefix T envelope',t+1,T,BASELINE_T[t])
 assert V==FINAL_VOLUME and sum(occ)==FINAL_VOLUME
 assert T<BASELINE_T_FINAL,('no strict gain',T)
 return T

def payload_from_responses(response):
 lines=response.splitlines();assert len(lines)==len(PUBLIC_COMMANDS)
 expected=[tuple(map(int,l.split()))for l in lines];rows=[]
 for n,v in zip(PUBLIC_COMMANDS,expected):
  assert len(v)==(2 if n>0 else 1)
  rows.append((n,v[1]if n>0 else -1))
 _audit(rows,expected);blob=_encode(rows);assert _decode(blob)==rows
 return blob

def _selected(payload):
 if payload is None:payload=SELECTED_PAYLOAD
 assert payload is not None,'public12 selection pending; no payload frozen yet'
 rows=_decode(payload);_audit(rows);return payload,rows

def _check_parent(old,rows):
 assert hashlib.sha256(base64.b64decode(old)).hexdigest()==OLD_PAYLOAD_SHA,'unexpected public12 parent payload'
 before=_decode(old);assert [n for n,x in before]==[n for n,x in rows]
 assert before[:FIXED]==rows[:FIXED],'first154 table decisions changed'

def apply_cpp(source,*,payload=None):
 blob,rows=_selected(payload)
 pattern=r'(static const char\* const encoded11\[\]=\{)(.*?)(\n\};)'
 matches=list(re.finditer(pattern,source,re.S));assert len(matches)==1
 m=matches[0];old=''.join(re.findall(r'"([^"]*)"',m[2]));_check_parent(old,rows)
 body='\n'+'\n'.join('"'+blob[i:i+120]+'",'for i in range(0,len(blob),120))
 return source[:m.start(2)]+body+source[m.end(2):]

def apply_cj(source,*,payload=None):
 assert 'class Transcript15 {'not in source and 'reconstructingTranscript'not in source,'cached Cj forbidden; transform uncached and regenerate its own output cache'
 blob,rows=_selected(payload)
 pattern=r'(func replayTable11\(\): ReplayTable \{)(.*?)(\n\})'
 matches=list(re.finditer(pattern,source,re.S));assert len(matches)==1
 m=matches[0];old=''.join(re.findall(r'decoder.feed\("([^"]*)"\)',m[2]));_check_parent(old,rows)
 body='\n    let decoder = ReplayDecoder()\n'+''.join('    decoder.feed("'+blob[i:i+4096]+'")\n'for i in range(0,len(blob),4096))+'    return decoder.finish()'
 return source[:m.start(2)]+body+source[m.end(2):]
